function patchMarkerBlockSwift(src, tpl, cfg) {
  const BRIDGE_BEGIN = `// ─── BEGIN ${cfg.name} (generated — do not edit here) ───`;
  const BRIDGE_END = `// ─── END ${cfg.name} ───`;
  const block = [
    BRIDGE_BEGIN,
    `// Source: app/native/${cfg.src} · written by scripts/sync-app-assets.js.`,
    '// Edit the repo file and re-run `npm run app:sync`; edits made here are overwritten.',
    tpl.replace(/\s+$/, ''),
    BRIDGE_END,
  ].join('\n');

  const b = src.indexOf(BRIDGE_BEGIN);
  const e = src.indexOf(BRIDGE_END);
  // Half a pair means someone hand-edited or the file was truncated. Appending a
  // second copy would give the target two `MTAudioBridge` types, and the compiler
  // error for that points nowhere near the cause. Refuse instead.
  if ((b < 0) !== (e < 0)) return { swift: src, note: `✗ ${cfg.label}: 标记不成对，拒绝改写` };
  if (b >= 0 && e < b) return { swift: src, note: `✗ ${cfg.label}: 标记顺序颠倒，拒绝改写` };

  let out;
  if (b >= 0) {
    const tail = e + BRIDGE_END.length + (src[e + BRIDGE_END.length] === '\n' ? 1 : 0);
    out = src.slice(0, b) + block + '\n' + src.slice(tail);
  } else {
    if (!BRIDGE_IMPORT_ANCHOR.test(src)) {
      return { swift: src, note: `✗ ${cfg.label}: import WebKit 锚点缺失 — 转换器模板变了？` };
    }
    out = src.replace(BRIDGE_IMPORT_ANCHOR, 'import WebKit\n\n' + block + '\n');
  }
  if (out === src) return { swift: src, note: `${cfg.label} already current` };
  return { swift: out, note: b >= 0 ? `${cfg.label} block replaced` : `${cfg.label} block inserted` };
}

// 音频桥那一支的具名入口。保留它有两个理由：test/build-scripts.test.js 直接调它，
// 而那组断言（幂等、标记不成对拒绝改写、锚点缺失报错）守的正是这段逻辑本身。
function patchAudioBridgeSwift(src, tpl) {
  return patchMarkerBlockSwift(src, tpl, BLOCKS[0]);
}

function patchAudioBridge(sharedDir) {
  const f = path.join(sharedDir, 'ViewController.swift');
  if (!fs.existsSync(f)) return '✗ bridges: no ViewController.swift';
  const notes = [];
  for (const cfg of BLOCKS) {
    const tplPath = path.join(ROOT, 'app', 'native', cfg.src);
    if (!fs.existsSync(tplPath)) { notes.push(`✗ ${cfg.label}: app/native/${cfg.src} 不存在`); continue; }
    const { swift, note } = patchMarkerBlockSwift(
      fs.readFileSync(f, 'utf8'), fs.readFileSync(tplPath, 'utf8'), cfg);
    if (!/^✗/.test(note)) fs.writeFileSync(f, swift);
    notes.push(note);
  }
  // 深链桥要在 WKWebView 最终确定之后 attach 一次；冷启动期间到达的 URL 存在
  // pending 里等它。漏了这一行的表现是「点了链接，App 打开了，然后什么都没发生」。
  const ATTACH = 'MTDeepLink.attach(self.webView)';
  let vc = fs.readFileSync(f, 'utf8');
  if (!vc.includes(ATTACH)) {
    const anchor = 'self.webView.navigationDelegate = self';
    if (!vc.includes(anchor)) notes.push('✗ deeplink attach: navigationDelegate 锚点缺失');
    else {
      vc = vc.replace(anchor, anchor + '\n\n'
        + '        // Patched by scripts/sync-app-assets.js — 跨面交接（learning-design §8.4.1.1）。\n'
        + '        ' + ATTACH);
      fs.writeFileSync(f, vc);
      notes.push('deeplink attach patched');
    }
  } else notes.push('deeplink attach already current');

  // Sign in with Apple：attach（拿 webView 做弹窗锚点）+ 一条**独立**的消息通道。
  // 独立而不是复用转换器那个 `controller` 通道，同 mtAudio 的理由：那个通道的函数体
  // 整个包在 #if os(macOS) 里，且开头就 `message.body as! String` —— 传字典会 trap。
  const A_ATTACH = 'MTAppleSignIn.attach(self.webView)';
  vc = fs.readFileSync(f, 'utf8');
  // 幂等判据必须覆盖**这一版要打的全部内容**，不能只认第一行。
  // 2026-09-03：加 MTWebAuth.attach 时判据还只认 MTAppleSignIn.attach，于是整段被
  // 当成「已经打过了」跳过 —— 补丁没打上，而输出说的是 already current。
  // 少一行 attach 的表现是：Google 那个按钮点了，系统鉴权会话拿不到窗口锚点。
  if (vc.includes(A_ATTACH) && !vc.includes('MTWebAuth.attach')) {
    vc = vc.replace(A_ATTACH, A_ATTACH + '\n            MTWebAuth.attach(self.webView)');
    fs.writeFileSync(f, vc);
    notes.push('apple attach: 补上 MTWebAuth.attach');
  } else if (!vc.includes(A_ATTACH)) {
    const anchor = 'self.webView.navigationDelegate = self';
    if (!vc.includes(anchor)) notes.push('✗ apple attach: navigationDelegate 锚点缺失');
    else {
      vc = vc.replace(anchor, anchor + '\n\n'
        + '        // Patched by scripts/sync-app-assets.js — 原生 Sign in with Apple（§8.4.1.2）。\n'
        + '        if #available(iOS 13.0, macOS 10.15, *) {\n'
        + '            ' + A_ATTACH + '\n'
        + '            MTWebAuth.attach(self.webView)\n'
        + '            self.webView.configuration.userContentController.add(\n'
        + '                MTAppleSignInRelay.shared, name: "mtAppleSignIn")\n'
        + '        }');
      fs.writeFileSync(f, vc);
      notes.push('apple attach patched');
    }
  } else notes.push('apple attach already current');

  // 文件面板（macOS）：uiDelegate 的唯一持有者。与 deeplink attach 同一个锚点、同一种幂等判据。
  const F_ATTACH = 'MTFilePanel.attach(self.webView)';
  vc = fs.readFileSync(f, 'utf8');
  if (!vc.includes(F_ATTACH)) {
    const anchor = 'self.webView.navigationDelegate = self';
    if (!vc.includes(anchor)) notes.push('✗ file panel attach: navigationDelegate 锚点缺失');
    else {
      vc = vc.replace(anchor, anchor + '\n'
        + '        // Patched by scripts/sync-app-assets.js — macOS 文件面板（§9.7 文档翻译）：没有它 <input type=file> 是死按钮。\n'
        + '        ' + F_ATTACH);
      fs.writeFileSync(f, vc);
      notes.push('file panel attach patched');
    }
  } else notes.push('file panel attach already current');
  return notes.join(' · ');
}

// Patch 3 (§9.4): the 说 exercise records the microphone inside the WKWebView.
// iOS requires NSMicrophoneUsageDescription in the APP target's Info.plist or the
// process is killed at getUserMedia time — and the converter's template does not
// carry it. `safari-project*/` is regenerated (and this key wiped) routinely, so
// the patch lives here, like every other thing the converter gets wrong for us.
// The string names the §10 Gate C contract (and, since 2026-09-07, Gate E — continuous
// listening in 对话 · 实时听译, learning-design §9.6), not a generic "needs the mic".
//
const MIC_KEY = 'NSMicrophoneUsageDescription';
// 2026-09-12（Gate H）：加了「或只在你的设备上识别」—— 设备内置转写时声音根本不出设备。
const MIC_TEXT = '朗读练习、「对话 · 实时听译」与 iPhone「实时字幕」（听外放的视频声音）需要使用麦克风：声音只在你的设备上识别，或只发送到你自己配置的转写端点，识别后立即丢弃，不保存任何录音，绝不存储或上传到我们的服务器。';

// One row per declaration. `only` names the platform App directory it belongs to;
// absent means every App target.
//
// `UIBackgroundModes` MUST be iOS-only, and it cannot ride `build-safari.sh`'s
// `set_app_key` to get there: that helper anchors on
// `PRODUCT_BUNDLE_IDENTIFIER = $BUNDLE_ID;`, and the perl line beside it rewrites
// EVERY bundle id in the project to the same value on purpose (one App Store record,
// two platforms) — so the setting would land on the macOS App target too. A macOS app
// declaring a background mode it cannot use is something review asks about, and
// macOS needs nothing here anyway: its process is never suspended (§9.5).
// 设备内置转写（§9.6.1）：SpeechAnalyzer 在本机跑，是否需要这个键 Apple 没写死；缺了它的
// 后果是进程被杀而不是报错，多一个键的代价是零。文案与 Gate H 同源（D6 同版换正式版）。
const SPEECH_KEY = 'NSSpeechRecognitionUsageDescription';
const SPEECH_TEXT = '「设备内置转写」在你的设备上识别语音，声音不发往任何服务器。';
// Gate I 表里那句（learning-design §10）。弹窗里引号会被当成 XML 属性界符的心智负担不值得 —— 用「」。
const AUDIO_CAPTURE_TEXT = '「实时字幕」会在你点开始后识别这台 Mac 正在播放的声音；声音只在本机识别或只发往你配置的转写端点，不录音、不保存。';

// 2026-09-18：1.12.1 国际 iOS 被拒（Guideline 4 - Design）：「权限请求的文案与 App 的本地化语言不一致」——
// 审核机是英文 iPad，App 界面跟着系统是英文，而上面三句只有中文、且包里没有任何 InfoPlist.strings。
