const PLIST_L10N_KEYS = [MIC_KEY, SPEECH_KEY, AUDIO_CAPTURE_KEY];

// ── 右键「服务」的菜单名 ───────────────────────────────────────────────────────────────────────
// Info.plist 里 NSMenuItem.default 的值既是英文菜单名，也是 ServicesMenu.strings 的键。品牌名在中文里是
// 「大肚猴」，其余语种不译（与 _locales 里 quick_menu_open 的写法一致）。清单与 PLIST_L10N 同一份 lproj。
const SERVICE_MESSAGE = 'translateSelection';           // = services.swift 里 @objc 方法名的第一段
const SERVICE_TITLE_EN = 'Translate with BelliedMonkey';
const SERVICES_L10N = {
  en: SERVICE_TITLE_EN,
  'zh-Hans': '用大肚猴翻译',
  'zh-Hant': '用大肚猴翻譯',
  ja: 'BelliedMonkey で翻訳',
  ko: 'BelliedMonkey로 번역',
  fr: 'Traduire avec BelliedMonkey',
  de: 'Mit BelliedMonkey übersetzen',
  es: 'Traducir con BelliedMonkey',
  ar: 'الترجمة باستخدام BelliedMonkey',
  'pt-BR': 'Traduzir com BelliedMonkey',
  ru: 'Перевести в BelliedMonkey',
  hi: 'BelliedMonkey से अनुवाद करें',
};
function servicesXml() {
  return '<array>\n\t\t<dict>\n'
    + `\t\t\t<key>NSMenuItem</key>\n\t\t\t<dict>\n\t\t\t\t<key>default</key>\n\t\t\t\t<string>${SERVICE_TITLE_EN}</string>\n\t\t\t</dict>\n`
    + `\t\t\t<key>NSMessage</key>\n\t\t\t<string>${SERVICE_MESSAGE}</string>\n`
    + '\t\t\t<key>NSPortName</key>\n\t\t\t<string>$(PRODUCT_NAME)</string>\n'
    + '\t\t\t<key>NSRequiredContext</key>\n\t\t\t<dict/>\n'
    + '\t\t\t<key>NSSendTypes</key>\n\t\t\t<array>\n\t\t\t\t<string>NSStringPboardType</string>\n\t\t\t\t<string>public.utf8-plain-text</string>\n\t\t\t</array>\n'
    + '\t\t</dict>\n\t</array>';
}
function servicesMenuStringsText(lproj) {
  const title = SERVICES_L10N[lproj];
  if (!title) throw new Error(`SERVICES_L10N 没有 ${lproj}`);
  const esc = (x) => x.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
  return '/* 右键「服务」的菜单名 —— 由 scripts/sync-app-assets.js 的 SERVICES_L10N 生成，不要手改（工程会被重生成）。 */\n'
    + `"${esc(SERVICE_TITLE_EN)}" = "${esc(title)}";\n`;
}

const PLIST_KEYS = [
  { key: MIC_KEY, xml: `<string>${MIC_TEXT_EN}</string>` },
  { key: SPEECH_KEY, xml: `<string>${SPEECH_TEXT_EN}</string>` },
  { key: 'UIBackgroundModes', only: 'iOS (App)',
    xml: '<array>\n\t\t<string>audio</string>\n\t</array>' },
  // 灵动岛（§9.5）。没有这个键，ActivityKit 在运行时直接拒绝启动 Live Activity ——
  // 而且**不抛异常**：`Activity.request` 返回失败，岛上什么都不发生。同 iOS-only。
  { key: 'NSSupportsLiveActivities', only: 'iOS (App)', xml: '<true/>' },
  // 实时字幕（learning-design §9.8 / §10 Gate I）：Mac 抓系统声音的权限说明。系统弹「想访问以录制你的系统音频」时，
  // 这句就是弹窗里那行字（尖刺 S1 截图为证）—— 不是屏幕录制权限。只给 macOS App：iOS 没有这个权限。
  // 缺了它，弹窗没有说明句、审核会问；build.js 的 Gate I 检查这一行在。
  { key: 'NSAudioCaptureUsageDescription', only: 'macOS (App)', xml: `<string>${AUDIO_CAPTURE_TEXT_EN}</string>` },
  // 快速翻译的右键「服务」（learning-design §9.9，M-4）。零权限取词的另一半：宿主 App 把选中的文字交过来。
  // **`NSRequiredContext` 必须在（空字典即可）**：没有它，服务「已登记、默认不启用、菜单里永远找不到、无报错」
  // （T2 尖刺实测）。NSPortName 用 $(PRODUCT_NAME)：两个 flavor 的 App 名不同，而它必须等于 App 名。
  // 菜单名的 12 个语种在 ServicesMenu.strings（SERVICES_L10N），这里的 default 是英文、也是那份表的键。
  { key: 'NSServices', only: 'macOS (App)', xml: servicesXml() },
  // 系统翻译扩展的联网许可（§9.9 / iOS 线 I-5）。**这个键写在宿主 App 的 Info.plist 里** ——
  // Apple 文档那句 “your app's Info.plist” 是字面意思。T1 尖刺把它写在扩展自己的 plist 里
  // 时，扩展里三个地址一律 NSURLError -1009（而同一时刻宿主 App 联网是 200）：不报权限
  // 错误，只是永远连不上。写进宿主之后，`api.deepseek.com` 与额度中继都可达，
  // 而且**不按域名限制** —— 自定义端点的自带 key 用户不受影响。
  { key: 'com.apple.developer.translation-ui-provider.network-access', only: 'iOS (App)', xml: '<true/>' },
];

// 一份 <lproj>/InfoPlist.strings 的内容（老式 .strings，plutil -lint 认）。三个键都写：iOS 用不到
// NSAudioCaptureUsageDescription，多一行无害；少写一份分支就多一处会漏的地方。
function infoPlistStringsText(lproj) {
  const rows = PLIST_L10N[lproj];
  if (!rows) throw new Error(`PLIST_L10N 没有 ${lproj}`);
  const esc = (s) => s.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
  return '/* 权限请求文案 —— 由 scripts/sync-app-assets.js 的 PLIST_L10N 生成，不要手改（工程会被重生成）。 */\n'
    + PLIST_L10N_KEYS.map((k, i) => `"${k}" = "${esc(rows[i])}";`).join('\n') + '\n';
}

// 纯函数：把 InfoPlist.strings 变体组挂进 pbxproj。照抄转换器给 Main.html 的写法（PBXVariantGroup +
// 每个 lproj 一个 PBXFileReference），挂到 Shared (App)/Resources 组、两个 App target 的 Resources 阶段
// （以「有 Main.html in Resources 的阶段」为准 —— 扩展与小组件都没有），knownRegions 补齐。
// 幂等：变体组已在就一字不改（文案改了只需重写 .strings 文件，不用动工程）。
const LID = (n) => 'MT1F0057A1B9' + String(n).padStart(12, '0');
// 两份 .strings 共用这一个补丁：InfoPlist.strings（权限文案，idBase 0 —— 出货至今的 ID 不动）与
// ServicesMenu.strings（右键「服务」的菜单名，idBase 100）。只有文件名与 ID 段不同。
function patchPbxprojStringsGroup(src, lprojs, file, idBase) {
  return _patchStringsGroup(src, lprojs, file, (n) => LID(idBase + n));
}
function patchPbxprojInfoPlistStrings(src, lprojs) { return patchPbxprojStringsGroup(src, lprojs, 'InfoPlist.strings', 0); }
function _patchStringsGroup(src, lprojs, FILE, LID) {
  if (src.includes(`/* ${FILE} */`)) return { src, note: `${FILE} already in project` };
  const need = ['/* End PBXBuildFile section */', '/* End PBXFileReference section */', '/* End PBXVariantGroup section */', 'knownRegions = ('];
  for (const n of need) if (!src.includes(n)) return { src, note: `✗ ${FILE}: 缺 ${n} —— 转换器布局变了？` };
  const groupRe = /(\t\t\t\t[0-9A-F]{24} \/\* Main\.html \*\/,\n)/;
  const phaseRe = /(\t\t\t\t[0-9A-F]{24} \/\* Main\.html in Resources \*\/,\n)/g;
  if (!groupRe.test(src)) return { src, note: `✗ ${FILE}: Resources 组里找不到 Main.html` };
  const phases = (src.match(phaseRe) || []).length;
  if (phases !== 2) return { src, note: `✗ ${FILE}: 期望 2 个 App Resources 阶段，找到 ${phases}` };

  const vg = LID(1);
  const refs = lprojs.map((l, i) => ({ l, id: LID(10 + i) }));
  let out = src;
  // ① PBXBuildFile：两个 App target 各一条
  out = out.replace('/* End PBXBuildFile section */',
    `\t\t${LID(2)} /* ${FILE} in Resources */ = {isa = PBXBuildFile; fileRef = ${vg} /* ${FILE} */; };\n`
    + `\t\t${LID(3)} /* ${FILE} in Resources */ = {isa = PBXBuildFile; fileRef = ${vg} /* ${FILE} */; };\n`
    + '/* End PBXBuildFile section */');
  // ② PBXFileReference：每个 lproj 一条
  out = out.replace('/* End PBXFileReference section */',
    refs.map((r) => `\t\t${r.id} /* ${r.l} */ = {isa = PBXFileReference; lastKnownFileType = text.plist.strings; name = "${r.l}"; path = "${r.l}.lproj/${FILE}"; sourceTree = "<group>"; };\n`).join('')
    + '/* End PBXFileReference section */');
  // ③ PBXVariantGroup
  out = out.replace('/* End PBXVariantGroup section */',
    `\t\t${vg} /* ${FILE} */ = {\n\t\t\tisa = PBXVariantGroup;\n\t\t\tchildren = (\n`
    + refs.map((r) => `\t\t\t\t${r.id} /* ${r.l} */,\n`).join('')
    + `\t\t\t);\n\t\t\tname = ${FILE};\n\t\t\tsourceTree = "<group>";\n\t\t};\n`
    + '/* End PBXVariantGroup section */');
  // ④ Resources 组 children
  out = out.replace(groupRe, `$1\t\t\t\t${vg} /* ${FILE} */,\n`);
  // ⑤ 两个 App target 的 Resources 阶段
  let n = 0;
  out = out.replace(phaseRe, (m) => m + `\t\t\t\t${n++ === 0 ? LID(2) : LID(3)} /* ${FILE} in Resources */,\n`);
  // ⑥ knownRegions
  out = out.replace(/knownRegions = \(\n([\s\S]*?)(\t\t\t\);)/, (m, body, close) => {
    const have = new Set(body.split('\n').map((s) => s.trim().replace(/,$/, '')).filter(Boolean));
    const add = lprojs.filter((l) => !have.has(l) && !have.has(`"${l}"`));
    return 'knownRegions = (\n' + body + add.map((l) => `\t\t\t\t${/[^A-Za-z0-9]/.test(l) ? `"${l}"` : l},\n`).join('') + close;
  });
  return { src: out, note: `${FILE} variant group added (${lprojs.length} lproj · 2 app targets)` };
}

function patchInfoPlistStrings(sharedDir) {
  return writeStringsGroup(sharedDir, Object.keys(PLIST_L10N), 'InfoPlist.strings', infoPlistStringsText, patchPbxprojInfoPlistStrings);
}
function patchServicesMenuStrings(sharedDir) {
  return writeStringsGroup(sharedDir, Object.keys(SERVICES_L10N), 'ServicesMenu.strings', servicesMenuStringsText,
    (src, lprojs) => patchPbxprojStringsGroup(src, lprojs, 'ServicesMenu.strings', 100));
}
function writeStringsGroup(sharedDir, lprojs, FILE, textOf, patchPbx) {
  const res = path.join(sharedDir, 'Resources');
  if (!fs.existsSync(res)) return 'no Resources/';
  let written = 0;
  for (const l of lprojs) {
    const dir = path.join(res, `${l}.lproj`);
    fs.mkdirSync(dir, { recursive: true });
    const f = path.join(dir, FILE);
    const text = textOf(l);
    if (!fs.existsSync(f) || fs.readFileSync(f, 'utf8') !== text) { fs.writeFileSync(f, text); written++; }
  }
  const appRoot = path.dirname(sharedDir);
  const xcodeproj = fs.readdirSync(appRoot).find((n) => n.endsWith('.xcodeproj'));
  if (!xcodeproj) return 'no xcodeproj';
  const f = path.join(appRoot, xcodeproj, 'project.pbxproj');
  if (!fs.existsSync(f)) return 'no project.pbxproj';
  const before = fs.readFileSync(f, 'utf8');
  const { src, note } = patchPbx(before, lprojs);
  if (src !== before) fs.writeFileSync(f, src);
  return `${note}${written ? `（写了 ${written} 份 .strings）` : ''}`;
}

// Pure, so the tests can run it without an Xcode tree. Returns { xml, added, note }.
function patchPlistXml(src, keys) {
  const added = [];
  const updated = [];
  let out = src;
  for (const k of keys) {
    const keyTag = `<key>${k.key}</key>`;
    if (out.includes(keyTag)) {
      // 键已在，但值可能是旧的（2026-09-07：麦克风文案改了措辞，工程里的 plist 却还是
      // 「识别后立即丢弃」那一版 —— 模拟器弹窗里看到的正是旧话）。只对 <string> 值做替换：
      // 数组/布尔那几个键没有「改措辞」这回事。
      const m = /^<string>[\s\S]*<\/string>$/.test(k.xml);
      if (m) {
        const re = new RegExp(keyTag.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\s*<string>[^<]*<\\/string>');
        const cur = re.exec(out);
        if (cur && cur[0] !== `${keyTag}\n\t${k.xml}` && !cur[0].endsWith(k.xml)) {
          out = out.replace(re, `${keyTag}\n\t${k.xml}`);
          updated.push(k.key);
        }
      }
      continue;
    }
    const anchor = out.lastIndexOf('</dict>');
    if (anchor < 0) return { xml: src, added: [], updated: [], note: '✗ no </dict> anchor' };
    out = out.slice(0, anchor) + `\t<key>${k.key}</key>\n\t${k.xml}\n` + out.slice(anchor);
    added.push(k.key);
  }
  const parts = [];
  if (added.length) parts.push(`patched ${added.join(', ')}`);
  if (updated.length) parts.push(`updated ${updated.join(', ')}`);
  return { xml: out, added, updated, note: parts.length ? parts.join(' · ') : 'already current' };
}

// 跨面交接的自定义 scheme（learning-design §8.4.1.1）。
//
// **两个 flavor 两个 scheme。** 同名的话，两版同时装在一台机器上时由 iOS 随机挑一个
// 去接 —— 而「跑的是哪一份」没有确定答案，正是 verification-spec §2.0 已经付过代价的
// 那件事。scheme 跟着工程树走（safari-project-china 是中国版）。
function schemeFor(sharedDir) {
  return /-china\b/.test(sharedDir) ? 'belliedmonkeycn' : 'belliedmonkey';
}

// 这棵树的 **App** bundle id（国际版 com.belliedmonkeytranslator、中国版 …cn）。
// 问工程，不按目录名猜：`build-safari.sh` 是唯一写它的地方，而 App Group 与共享
// Keychain 组的名字都跟着它走（§9.9）。两个 flavor 共用一个组，等于让两份装在同一台
// 机器上的 App 互相看得见对方的 key。
function appBundleId(sharedDir) {
  const appRoot = path.dirname(sharedDir);
  const xcodeproj = fs.readdirSync(appRoot).find((n) => n.endsWith('.xcodeproj'));
  if (!xcodeproj) return '';
  const f = path.join(appRoot, xcodeproj, 'project.pbxproj');
  if (!fs.existsSync(f)) return '';
  const m = fs.readFileSync(f, 'utf8').match(/PRODUCT_BUNDLE_IDENTIFIER = "?([a-zA-Z0-9.]+)"?;/);
  return m ? m[1].replace(/\.extension$/, '') : '';
}

function urlTypeXml(scheme) {
  return '<array>\n\t\t<dict>\n'
    + '\t\t\t<key>CFBundleURLName</key>\n'
    + `\t\t\t<string>cc.belliedmonkey.deeplink</string>\n`
    + '\t\t\t<key>CFBundleURLSchemes</key>\n'
    + `\t\t\t<array>\n\t\t\t\t<string>${scheme}</string>\n\t\t\t</array>\n`
    + '\t\t</dict>\n\t</array>';
}

// 平台入口：把外部打开的 URL 交给 MTDeepLink。iOS 走 SceneDelegate（两支：冷启动的
// connectionOptions 与热启动的 openURLContexts —— 只接一支的表现是「App 没开着时点
// 链接没反应」，而那不会报任何错），macOS 走 AppDelegate。
// 一行常量式的针脚补丁，"含它就跳过" 在这里是对的。
const DELEGATE_PATCHES = [
  {
    file: 'iOS (App)/SceneDelegate.swift',
    needle: 'MTDeepLink.handle',
    anchor: 'guard let _ = (scene as? UIWindowScene) else { return }',
    add: (a) => a + '\n'
      + '        // Patched by scripts/sync-app-assets.js — 跨面交接（§8.4.1.1）。\n'
      + '        // 冷启动这一支：App 是被这条 URL 拉起来的。\n'
      + '        if let ctx = connectionOptions.urlContexts.first { MTDeepLink.handle(ctx.url) }\n'
      + '    }\n\n'
      + '    // 热启动这一支：App 已经在后台开着。\n'
      + '    func scene(_ scene: UIScene, openURLContexts URLContexts: Set<UIOpenURLContext>) {\n'
      + '        if let ctx = URLContexts.first { MTDeepLink.handle(ctx.url) }',
  },
  {
    file: 'macOS (App)/AppDelegate.swift',
    needle: 'MTDeepLink.handle',
    anchor: '    func applicationDidFinishLaunching(_ notification: Notification) {',
    add: (a) => '    // Patched by scripts/sync-app-assets.js — 跨面交接（§8.4.1.1）。\n'
      + '    func application(_ application: NSApplication, open urls: [URL]) {\n'
      + '        if let u = urls.first { MTDeepLink.handle(u) }\n'
      + '    }\n\n' + a,
  },
  // 实时字幕（learning-design §9.8 协议补充决定 14）：会话中主窗口「关了」其实是 orderOut，最后一个窗口
  // 关了也不退出；点 Dock 找回主窗口。转换器模板在这里是一行 return true。
  {
    file: 'macOS (App)/AppDelegate.swift',
    what: 'subtitle session',
    // 2026-09-19：快速翻译的常驻（§9.9）要同一条规则 ——「含 needle 即跳过」式的补丁叠不了第二个，
    // 所以是**改写**这一项：needle 换成两个条件都在的那一行。已经打过旧版补丁的树（只认字幕会话的那一行）
    // 由 upgrade 原地升级：那一行是我们自己写进去的、逐字已知，换掉它比逼着人重新生成整棵工程便宜，
    // 也比落到「锚点缺失」更有用。两种形状都不是 ⇒ 仍然响亮地失败。
    upgrade: { from: '        return !MTSubtitleBar.sessionActive\n', to: '        return !(MTSubtitleBar.sessionActive || MTResident.keepAlive)\n' },
    needle: 'MTSubtitleBar.sessionActive || MTResident.keepAlive',
    anchor: '    func applicationShouldTerminateAfterLastWindowClosed(_ sender: NSApplication) -> Bool {\n        return true\n    }',
    add: () => '    // Patched by scripts/sync-app-assets.js — 实时字幕（§9.8）会话中、或快速翻译常驻开着（§9.9）时，关主窗口是收起，不退出。\n'
      + '    func applicationShouldTerminateAfterLastWindowClosed(_ sender: NSApplication) -> Bool {\n'
      + '        return !(MTSubtitleBar.sessionActive || MTResident.keepAlive)\n'
      + '    }\n\n'
      + '    // 点 Dock 找回被收起的主窗口。\n'
      + '    func applicationShouldHandleReopen(_ sender: NSApplication, hasVisibleWindows flag: Bool) -> Bool {\n'
      + '        if !flag { MTSubtitleBar.showMainWindow() }\n'
      + '        return true\n'
      + '    }',
  },
];

function patchDelegates(sharedDir) {
  const appRoot = path.dirname(sharedDir);
  const notes = [];
  for (const p of DELEGATE_PATCHES) {
    const f = path.join(appRoot, p.file);
    if (!fs.existsSync(f)) continue;          // 这棵树没有这个平台
    const src = fs.readFileSync(f, 'utf8');
    const label = p.file.split('/')[0];
    const what = p.what || 'deeplink';
    if (src.includes(p.needle)) { notes.push(`${label}: ${what} already current`); continue; }
    if (p.upgrade && src.includes(p.upgrade.from)) {
      fs.writeFileSync(f, src.replace(p.upgrade.from, p.upgrade.to));
      notes.push(`${label}: ${what} upgraded`); continue;
    }
    if (!src.includes(p.anchor)) { notes.push(`✗ ${label}: ${what} 锚点缺失 — 转换器模板变了？`); continue; }
    fs.writeFileSync(f, src.replace(p.anchor, p.add(p.anchor)));
    notes.push(`${label}: ${what} patched`);
  }
  return notes.length ? notes.join(' · ') : 'no delegates found';
}

function patchInfoPlists(sharedDir) {
  const appRoot = path.dirname(sharedDir);   // …/<name>/, holding "iOS (App)" etc.
  const notes = [];
  const scheme = schemeFor(sharedDir);
  for (const entry of fs.readdirSync(appRoot)) {
    if (!/\(App\)$/.test(entry) || entry.startsWith('Shared')) continue;
    const plist = path.join(appRoot, entry, 'Info.plist');
    if (!fs.existsSync(plist)) continue;
    // scheme 两个平台都要：macOS App 同样可以被 URL 唤起。
    const keys = PLIST_KEYS.filter((k) => !k.only || k.only === entry)
      .concat([{ key: 'CFBundleURLTypes', xml: urlTypeXml(scheme) }]);
    const { xml, note } = patchPlistXml(fs.readFileSync(plist, 'utf8'), keys);
    if (/^✗/.test(note)) { notes.push(`✗ ${entry}: ${note.slice(2)}`); continue; }
    fs.writeFileSync(plist, xml);
    notes.push(entry + ': ' + note);
  }
  return notes.length ? notes.join(' · ') : 'no app Info.plist found';
}

// Patch 4 (§9.4): the sandboxed macOS App also needs the audio-input sandbox
// entitlement, or getUserMedia is denied regardless of the Info.plist string. The
// converter uses Xcode 15+ build-settings-based entitlements (no .entitlements
// file — `ENABLE_APP_SANDBOX = YES` in the pbxproj), so the grant is the sibling
// build setting `ENABLE_RESOURCE_ACCESS_AUDIO_INPUT`, inserted ONLY into build
// configurations that belong to the macOS APP target (matched by its
// INFOPLIST_FILE — the extension target never records audio and stays ungranted).
// Idempotent, like every patch here; regeneration wipes it, app:sync restores it.
// Patch 4b (§8.4.1.2): Sign in with Apple 的 entitlement。
//
// 它**没有**构建设置的写法（沙箱与录音有，这个没有），只能来自一个 .entitlements
// 文件。所以这一处是这份脚本里唯一往工程里放新文件、并改 CODE_SIGN_ENTITLEMENTS 的补丁。
//
// 只挂给两个 App target（按 INFOPLIST_FILE 认），**不挂扩展** —— 扩展不登录，
// 多一个权限只会在审核时被问。
//
// 判据在别处：归档之后 `codesign -d --entitlements` 要能同时读到 applesignin 与
// 沙箱 —— 「构建没报错」说明不了两者是否共存（verify:ios 覆盖不到 entitlement）。
// 每个 target 一份 entitlements（I-2，learning-design §9.9）。原来是一份文件挂给两个 App
// target —— 而系统翻译要给 **iOS App 与它的扩展** 加 App Group / 共享 Keychain，给 macOS
// 加就是白给：那边没有 TranslationUIProvider，多出来的能力只会在审核时被问。
//
// 认哪个 target 用哪一份，靠的是「CODE_SIGN_ENTITLEMENTS（可能还没有）+ 紧随其后的
// INFOPLIST_FILE」这一对 —— 补丁一直把前者插在后者正上方，所以这一对就是「某个 target 的
// 某一档配置」的指纹。守卫也按这一对判：**不能用「整份 pbxproj 里出现过 CODE_SIGN_ENTITLEMENTS」**，
// 那样第二个 target 永远挂不上，而且不会有任何一行输出说这件事。
const ENTITLEMENTS = [
  { plist: 'iOS (App)/Info.plist', src: 'ios-app.entitlements' },
  { plist: 'macOS (App)/Info.plist', src: 'macos-app.entitlements' },
];

function patchEntitlements(sharedDir) {
  const appRoot = path.dirname(sharedDir);
  const xcodeproj = fs.readdirSync(appRoot).find((n) => n.endsWith('.xcodeproj'));
  if (!xcodeproj) return 'no xcodeproj';
  const f = path.join(appRoot, xcodeproj, 'project.pbxproj');
  if (!fs.existsSync(f)) return 'no project.pbxproj';

  let src = fs.readFileSync(f, 'utf8');
  const shared = path.basename(sharedDir);
  const done = [];
  const missing = [];
  let updated = 0;

  for (const e of ENTITLEMENTS) {
    // ① 文件本身（放进 Shared (App)/，与一次性的工程同生共死）
    const tplPath = path.join(ROOT, 'app', 'native', 'entitlements', e.src);
    if (!fs.existsSync(tplPath)) return `✗ entitlements: app/native/entitlements/${e.src} 不存在`;
    // `__MT_APP_BUNDLE_ID__` → 这棵树的 App bundle id（App Group 与共享 Keychain 组的名字
    // 都跟着它走）。读不到就整体放弃：写进去的组名会指向一个不存在的组，而那不报错 ——
    // 症状是「App 写了、扩展读不到」，钥匙串只回一个 -25300。
    const subs = extSubs(sharedDir);
    const raw = fs.readFileSync(tplPath, 'utf8');
    if (raw.includes('__MT_APP_BUNDLE_ID__') && !subs.__MT_APP_BUNDLE_ID__) {
      return `✗ entitlements: 工程里读不到 App 的 bundle id —— ${e.src} 会指向一个不存在的组`;
    }
    const tpl = applySubs(raw, subs);
    const dst = path.join(sharedDir, e.src);
    if (!fs.existsSync(dst) || fs.readFileSync(dst, 'utf8') !== tpl) { fs.writeFileSync(dst, tpl); updated += 1; }

    // ② 构建设置。三种情况都要处理：没有就插入；指着别处（例如拆分前那份共用的
    //    app.entitlements）就改写；已经对了就不动。
    const rel = shared + '/' + e.src;
    const quoted = e.plist.replace(/[.()]/g, (c) => '\\' + c);
    const pair = new RegExp('(\\n\\s*CODE_SIGN_ENTITLEMENTS = "[^"]*";)?(\\n(\\s*))INFOPLIST_FILE = "' + quoted + '";', 'g');
    let hits = 0;
    let found = 0;
    src = src.replace(pair, (m, had, ws, indent) => {
      found += 1;
      if (had && had.indexOf('"' + rel + '"') >= 0) return m;
      hits += 1;
      const tail = had ? m.slice(had.length) : m;
      return '\n' + indent + 'CODE_SIGN_ENTITLEMENTS = "' + rel + '";' + tail;
    });
    if (hits) done.push(`${e.src} ×${hits}`);
    if (!found) missing.push(e.plist);
  }

  // 一段都没认出来 ⇒ 转换器布局变了，整体放弃并说明（绝不写一半）
  if (missing.length) {
    return `✗ entitlements: 没找到 ${missing.join(' / ')} 那一段 —— 转换器布局变了？`;
  }
  if (done.length) { fs.writeFileSync(f, src); return `entitlements patched (${done.join(', ')})`; }
  return `entitlements already patched${updated ? '（文件已更新）' : ''}`;
}

// Patch 10 (§9.6.1): 本机离线朗读要链接 sherpa-onnx + onnxruntime（app/native/vendor/，由
// scripts/fetch-native-deps.js 拉取、钉版本 + sha256）。走**本地 SwiftPM 包**而不是手写
// LIBRARY_SEARCH_PATHS：xcframework 的平台切片、模拟器切片、C 模块映射全由 SPM 处理，
// 而每平台一行搜索路径的写法在 Xcode 升级时最先坏。
//
// 这是这份脚本里第二处往 pbxproj 里造对象的补丁（第一处是 widget target）。造得极少：
// 一个 XCLocalSwiftPackageReference、一个 XCSwiftPackageProductDependency，App target 的
// `packageProductDependencies` 列表（转换器本来就生成了空列表）各加一项，PBXProject 加
// `packageReferences`。扩展 target 不链接 —— 扩展里没有朗读模型。
const SPM_REF_ID = 'MT10D06CA57E0000000031';
const SPM_DEP_ID = 'MT10D06CA57E0000000032';
function patchSwiftPackageText(src, relPath) {
  if (src.includes(SPM_REF_ID)) return { src, note: 'sherpa package already patched' };
  const vendorOk = fs.existsSync(path.join(ROOT, 'app', 'native', 'vendor', 'sherpa-onnx', 'Package.swift'));
  if (!vendorOk) return { src, note: '✗ sherpa package: app/native/vendor/ 未就位 —— 先跑 node scripts/fetch-native-deps.js' };
  let out = src;
  // ① App target 的 packageProductDependencies（按紧邻的 name 行认，只认 (iOS)/(macOS) 两个 App）。
  //
  // **空列表不一定在。** 2026-09-20 重新生成工程时发现：转换器（Xcode 27）不再输出
  // `packageProductDependencies = ();` 这一行了，而这个补丁原来只会往已有的空列表里塞。
  // 于是它响亮地停下 —— 这是对的，但停下之后没人能往前走：离线朗读 / 设备内置转写那一整块
  // 链接不上，构建报的是 `Unable to resolve module dependency: 'SherpaOnnxC'`，离真因隔着两层。
  // 现在两种形状都认：有空列表就往里塞，没有就在 name 行后面补一个。
  let hits = 0;
  out = out.replace(/(name = "([^"]*) \((iOS|macOS)\)";\n\t\t\tpackageProductDependencies = \(\n)(\t\t\t\);)/g, (m, head, base, plat, tail) => {
    if (/Extension/.test(base)) return m;   // 扩展 target 的名字也带 (iOS)/(macOS)，不链接
    hits += 1;
    return head + `\t\t\t\t${SPM_DEP_ID} /* sherpa-onnx */,\n` + tail;
  });
  if (!hits) {
    out = out.replace(/(\t\t\tname = "([^"]*) \((iOS|macOS)\)";\n)(?!\t\t\tpackageProductDependencies)/g, (m, head, base) => {
      if (/Extension/.test(base)) return m;
      hits += 1;
      return head + `\t\t\tpackageProductDependencies = (\n\t\t\t\t${SPM_DEP_ID} /* sherpa-onnx */,\n\t\t\t);\n`;
    });
  }
  if (hits !== 2) return { src, note: `✗ sherpa package: App target 的 packageProductDependencies 命中 ${hits} 处（期望 2）—— 转换器布局变了？` };
  // ② PBXProject 的 packageReferences
  const PROJ_ANCHOR = '\t\t\tproductRefGroup = ';
  if (!out.includes(PROJ_ANCHOR)) return { src, note: '✗ sherpa package: PBXProject 的 productRefGroup 锚点缺失' };
  out = out.replace(PROJ_ANCHOR, `\t\t\tpackageReferences = (\n\t\t\t\t${SPM_REF_ID} /* XCLocalSwiftPackageReference "${relPath}" */,\n\t\t\t);\n` + PROJ_ANCHOR);
  // ③ 两个对象，放在 rootObject 之前
  const TAIL = '\t};\n\trootObject = ';
  if (!out.includes(TAIL)) return { src, note: '✗ sherpa package: rootObject 锚点缺失' };
  const objs = [
    '/* Begin XCLocalSwiftPackageReference section */',
    `\t\t${SPM_REF_ID} /* XCLocalSwiftPackageReference "${relPath}" */ = {`,
    '\t\t\tisa = XCLocalSwiftPackageReference;',
    `\t\t\trelativePath = "${relPath}";`,
    '\t\t};',
    '/* End XCLocalSwiftPackageReference section */',
    '',
    '/* Begin XCSwiftPackageProductDependency section */',
    `\t\t${SPM_DEP_ID} /* sherpa-onnx */ = {`,
    '\t\t\tisa = XCSwiftPackageProductDependency;',
    `\t\t\tpackage = ${SPM_REF_ID} /* XCLocalSwiftPackageReference "${relPath}" */;`,
    '\t\t\tproductName = "sherpa-onnx";',
    '\t\t};',
    '/* End XCSwiftPackageProductDependency section */',
  ].join('\n');
  out = out.replace(TAIL, objs + '\n' + TAIL);
  return { src: out, note: 'sherpa package patched (2 App targets)' };
}

// 部署目标钉到 build/os-floor.config.js 的下限（2026-09-13 用户裁定 iOS 16.4 / macOS 13.3，为的是
// 「优质」档系统语音与 Safari 16.4 一代的 WebKit）。转换器每次重生成都写回它自己的默认值（iOS 15.0 /
// macOS 10.14），所以这里每次 sync 都要重钉；只往上抬，不往下压（widget 目标自带更高的值，不动）。
// 历史：此前只把 macOS 从 10.14 抬到 10.15（sherpa-onnx 包的要求）。
const OS_FLOOR = require(path.join(ROOT, 'build', 'os-floor.config.js'));
function patchDeploymentTargets(src, floor) {
  const f = floor || OS_FLOOR.FLOOR;
  let n = 0;
  const bump = (text, key, want) => text.replace(new RegExp(key + ' = ([0-9.]+);', 'g'), (m, cur) => {
    if (OS_FLOOR.cmp(cur, want) >= 0) return m;
    n++; return `${key} = ${want};`;
  });
  let out = bump(src, 'IPHONEOS_DEPLOYMENT_TARGET', f.ios);
  out = bump(out, 'MACOSX_DEPLOYMENT_TARGET', f.macos);
  if (!n) return { src, note: `deployment targets already ≥ iOS ${f.ios} / macOS ${f.macos}` };
  return { src: out, note: `deployment targets → iOS ${f.ios} / macOS ${f.macos}（${n} 处）` };
}
// 旧名保留给测试与调用方：语义已并入 patchDeploymentTargets。
const patchMacDeploymentTarget = (src) => patchDeploymentTargets(src);

function patchSwiftPackage(sharedDir) {
  const appRoot = path.dirname(sharedDir);
  const xcodeproj = fs.readdirSync(appRoot).find((n) => n.endsWith('.xcodeproj'));
  if (!xcodeproj) return 'no xcodeproj';
  const f = path.join(appRoot, xcodeproj, 'project.pbxproj');
  if (!fs.existsSync(f)) return 'no project.pbxproj';
  // 相对路径从 .xcodeproj 所在目录算（safari-project/<App>/ → ../../app/native/vendor/sherpa-onnx）
  const rel = path.relative(appRoot, path.join(ROOT, 'app', 'native', 'vendor', 'sherpa-onnx')).split(path.sep).join('/');
  const { src, note } = patchSwiftPackageText(fs.readFileSync(f, 'utf8'), rel);
  if (!/^✗/.test(note) && !/already/.test(note)) fs.writeFileSync(f, src);
  const dt = patchDeploymentTargets(fs.readFileSync(f, 'utf8'));
  if (!/already/.test(dt.note)) fs.writeFileSync(f, dt.src);
  return note + ' · ' + dt.note;
}

function patchPbxproj(sharedDir) {
  const appRoot = path.dirname(sharedDir);
  const xcodeproj = fs.readdirSync(appRoot).find((n) => n.endsWith('.xcodeproj'));
  if (!xcodeproj) return 'no xcodeproj';
  const f = path.join(appRoot, xcodeproj, 'project.pbxproj');
  if (!fs.existsSync(f)) return 'no project.pbxproj';
  let src = fs.readFileSync(f, 'utf8');
  if (src.includes('ENABLE_RESOURCE_ACCESS_AUDIO_INPUT')) return 'audio-input entitlement already patched';
  // The sandbox line and the INFOPLIST_FILE line that identifies the target sit a
  // few (alphabetically sorted) settings apart — match the span WITHIN one build
  // configuration block (no `}` may intervene), so an extension target's sandbox
  // line can never borrow the app target's identifier line.
  const NEEDLE = /ENABLE_APP_SANDBOX = YES;((?:\n[^\n}]*){0,10}?\n\s*INFOPLIST_FILE = "macOS \(App\)\/Info\.plist";)/g;
  let hits = 0;
  src = src.replace(NEEDLE, (m, tail) => {
    hits++;
    return 'ENABLE_APP_SANDBOX = YES;\n\t\t\t\tENABLE_RESOURCE_ACCESS_AUDIO_INPUT = YES;' + tail;
  });
  if (!hits) return 'audio-input: macOS (App) sandbox block not found — converter layout changed?';
  fs.writeFileSync(f, src);
  return `audio-input entitlement patched (${hits} configs)`;
}

// Patch 5: the macOS host window. The converter's storyboard gives it
// `styleMask titled+closable` and nothing else — no resize, no zoom, no
// miniaturize — plus `fullScreenNone`, at a fixed 425×325. That is a sane window
// for what the template puts inside it (the 979-byte "this is your extension"
// placeholder). It is the wrong window for a reading app.
//
// Nobody saw it for three releases because nobody could see the content either:
// the same tree that never got its resources (see classifyProject above) shipped
// the placeholder, and a placeholder does not care how big it is. build 16 put
// the real review app in that window for the first time, and the smoke test
// walked straight into a 425pt box the user cannot enlarge — no drag, no zoom,
// not even full screen.
//
// Only the window is wrong: the wkWebView already carries
// `widthSizable/heightSizable`, so it follows the frame once the frame can move.
//
// The three template rects (contentRect, the view, the web view) all agree on
// the same size, and IB keeps them in sync when a human resizes the window — so
// the patch reads the size off contentRect and moves all of them together,
// instead of hardcoding a number the converter is free to change.
const WIN_W = 820;
const WIN_H = 640;
function patchMacWindowXml(src) {
  const STYLE_RE = /<windowStyleMask key="styleMask"((?:\s+[\w-]+="[^"]*")*)\s*\/>/;
  const style = src.match(STYLE_RE);
  if (!style) return { xml: src, note: 'window: styleMask not found — converter layout changed?' };
  if (/\bresizable="YES"/.test(style[1])) return { xml: src, note: 'window already patched' };

  const notes = [];
  // Keep whatever the converter set, add what a document window needs.
  let out = src.replace(STYLE_RE,
    `<windowStyleMask key="styleMask"${style[1]} miniaturizable="YES" resizable="YES"/>`);
  notes.push('resizable');

  const FULLSCREEN_RE = /(<windowCollectionBehavior key="collectionBehavior")\s+fullScreenNone="YES"\s*\/>/;
  if (FULLSCREEN_RE.test(out)) {
    out = out.replace(FULLSCREEN_RE, '$1 fullScreenPrimary="YES"/>');
    notes.push('fullscreen');
  }

  const rect = out.match(/<rect key="contentRect"[^/]*?width="([\d.]+)" height="([\d.]+)"\s*\/>/);
  if (rect) {
    const w = rect[1].replace(/\./g, '\\.');
    const h = rect[2].replace(/\./g, '\\.');
    // screenRect is a different size, so it is untouched; the view and the web
    // view share the template's content size and move with it.
    out = out.replace(new RegExp(`width="${w}" height="${h}"`, 'g'),
      `width="${WIN_W}" height="${WIN_H}"`);
    notes.push(`${WIN_W}×${WIN_H}`);
  } else {
    notes.push('contentRect not found — size left alone');
  }

  return { xml: out, note: `window patched (${notes.join(' · ')})` };
}

function patchMacWindow(sharedDir) {
  const appRoot = path.dirname(sharedDir);
  const f = path.join(appRoot, 'macOS (App)', 'Base.lproj', 'Main.storyboard');
  if (!fs.existsSync(f)) return 'no macOS storyboard';
  const src = fs.readFileSync(f, 'utf8');
  const { xml, note } = patchMacWindowXml(src);
  if (xml !== src) fs.writeFileSync(f, xml);
  return note;
}

// Patch 6: the macOS menu bar. The converter's storyboard gives the app exactly two
// top-level menus — the app menu and Help — and `AppDelegate.swift` builds none, so
// there is no Edit menu anywhere.
//
// That is not cosmetic. AppKit routes ⌘V as a key equivalent: NSApplication offers it
// to the main menu FIRST, and only a menu item carrying `paste:` claims it. With no
// such item the keystroke falls through as a plain keyDown, and a plain keyDown does
// not paste — WKWebView pastes in response to the `paste:` NSResponder action, which
// nothing ever sends. So ⌘V / ⌘C / ⌘X / ⌘A / ⌘Z are all dead, and ⌘W / ⌘M with them.
//
// It has never hurt a user, because every shipped macOS build so far carried the
// converter's 979-byte placeholder — no text field to paste into. 1.5.0 is the first
// build where it bites, and it bites on the FIRST screen: pasting an email address and
// then a verification code is the whole of onboarding.
//
// The menu is data here, not a 70-line string literal: hand-indented IB XML is where
// this kind of patch rots.
const MAC_MENUS = [
  { title: 'File', items: [
    { title: 'Close', key: 'w', sel: 'performClose:' },
  ] },
  { title: 'Edit', items: [
    { title: 'Undo', key: 'z', sel: 'undo:' },
    { title: 'Redo', key: 'Z', sel: 'redo:', mods: 'shift="YES" command="YES"' },
    { sep: true },
    { title: 'Cut', key: 'x', sel: 'cut:' },
    { title: 'Copy', key: 'c', sel: 'copy:' },
    { title: 'Paste', key: 'v', sel: 'paste:' },
    { title: 'Delete', sel: 'delete:' },
    { sep: true },
    { title: 'Select All', key: 'a', sel: 'selectAll:' },
  ] },
  // systemMenu="window" hands the window list to AppKit, same as the app/help menus.
  { title: 'Window', systemMenu: 'window', items: [
    { title: 'Minimize', key: 'm', sel: 'performMiniaturize:' },
    { title: 'Zoom', sel: 'performZoom:' },
  ] },
];

const slug = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-');

function renderMacMenus(target, pad) {
  const L = [];
  const at = (n, s) => L.push(' '.repeat(pad + n) + s);
  for (const menu of MAC_MENUS) {
    const m = slug(menu.title);
    at(0, `<menuItem title="${menu.title}" id="mt-mi-${m}">`);
    at(4, '<modifierMask key="keyEquivalentModifierMask"/>');
    at(4, `<menu key="submenu" title="${menu.title}"`
      + (menu.systemMenu ? ` systemMenu="${menu.systemMenu}"` : '') + ` id="mt-menu-${m}">`);
    at(8, '<items>');
    let sepN = 0;
    for (const it of menu.items) {
      if (it.sep) { at(12, `<menuItem isSeparatorItem="YES" id="mt-sep-${m}-${++sepN}"/>`); continue; }
      const s = slug(it.title);
      at(12, `<menuItem title="${it.title}"${it.key ? ` keyEquivalent="${it.key}"` : ''} id="mt-it-${m}-${s}">`);
      // Mirror the converter's own convention: a bare keyEquivalent means ⌘, an item
      // with no shortcut still carries an empty mask, and anything else spells it out.
      if (it.mods) at(16, `<modifierMask key="keyEquivalentModifierMask" ${it.mods}/>`);
      else if (!it.key) at(16, '<modifierMask key="keyEquivalentModifierMask"/>');
      at(16, '<connections>');
      at(20, `<action selector="${it.sel}" target="${target}" id="mt-ac-${m}-${s}"/>`);
      at(16, '</connections>');
      at(12, '</menuItem>');
    }
    at(8, '</items>');
    at(4, '</menu>');
    at(0, '</menuItem>');
  }
  return L.join('\n') + '\n';
}

function patchMacMenuXml(src) {
  if (/selector="paste:"/.test(src)) return { xml: src, note: 'menu already patched' };
  const HELP_RE = /^([ \t]*)<menuItem title="Help"/m;
  const anchor = src.match(HELP_RE);
  if (!anchor) return { xml: src, note: 'menu: Help anchor not found — converter layout changed?' };
  // The First Responder object id is generated per project, so read it off an action
  // the converter already wired instead of hardcoding one (same reflex as Patch 5
  // reading the size off contentRect).
  const fr = src.match(/<action selector="terminate:" target="([^"]+)"/);
  if (!fr) return { xml: src, note: 'menu: First Responder target not found — converter layout changed?' };
  const pad = anchor[1].length;
  const xml = src.replace(HELP_RE, renderMacMenus(fr[1], pad) + anchor[1] + '<menuItem title="Help"');
  return { xml, note: `menu patched (${MAC_MENUS.map((m) => m.title).join(' · ')})` };
}

function patchMacMenu(sharedDir) {
  const appRoot = path.dirname(sharedDir);
  const f = path.join(appRoot, 'macOS (App)', 'Base.lproj', 'Main.storyboard');
  if (!fs.existsSync(f)) return 'no macOS storyboard';
  const src = fs.readFileSync(f, 'utf8');
  const { xml, note } = patchMacMenuXml(src);
  if (xml !== src) fs.writeFileSync(f, xml);
  return note;
}


// ─── Patch 7: App 图标 —— 转换器的白框病（2026-08-15 真机截图坐实） ─────────
// safari-web-extension-converter 生成 AppIcon.appiconset 时，把扩展的 128px
// 圆角图标放大后【居中贴在白底画布】上：iOS 主屏图标要求满幅不透明正方形
// （圆角 iOS 自己裁），于是主屏上出现一圈白框，图还是糊的。
// 修法：仓库 app/appicon/ 里存两套定稿 —— ios-1024.png（满幅、不圆角、不透明）
// 与 mac-icon-*（圆角稿 + Apple 网格 824/1024 留白、四角透明，macOS 规范）——
// 每次 app:sync 原样覆写转换器的同名文件。文件名与 Contents.json 保持转换器
// 的命名，所以 pbxproj / json 都不用动。
function patchAppIcon(sharedDir) {
  const iconSrc = path.join(ROOT, 'app', 'appicon');
  if (!fs.existsSync(iconSrc)) return 'appicon: no app/appicon/, skipped';
  const set = path.join(sharedDir, 'Assets.xcassets', 'AppIcon.appiconset');
  if (!fs.existsSync(set)) return 'appicon: no AppIcon.appiconset';
  let n = 0;
  fs.copyFileSync(path.join(iconSrc, 'ios-1024.png'), path.join(set, 'universal-icon-1024@1x.png')); n++;
  for (const f of fs.readdirSync(iconSrc)) {
    if (!f.startsWith('mac-icon-')) continue;
    fs.copyFileSync(path.join(iconSrc, f), path.join(set, f)); n++;
  }
  return `appicon replaced (${n} files, full-bleed iOS + margined mac)`;
}

// Patch 11 (§9.5 灵动岛): 造一个 WidgetKit 扩展 target 承载 Live Activity。
//
// **这是本仓库里唯一一个凭空造 target 的补丁，也是最脆的一个。** 别的补丁都是往一个
// 已经在 target 里的文件上贴代码；这一个要在 pbxproj 里新增八类对象并把它们接起来，
// 而 `safari-project*/` 每次重新生成都会把它们全部抹掉。
//
// 之所以还敢做：**转换器自己已经生成了「Safari 扩展嵌进 App」的完整结构**，Widget 扩展
// 是同一个形状（productType 只差一个字），所以这里是照着抄，而不是凭空发明。抄的对象
// 就在同一个文件里，形状漂移时对照得出来。
//
// 幂等：见到 needle 就跳过。**造了一半就中断会留下一个编译不了的工程**，所以每一步都
// 先检查、任何一步的锚点缺失都整体放弃（而不是写一半），并把原因说出来。
// iOS 扩展 target 的规格。转换器只会生成 App 与 Safari 扩展两个 target，别的（灵动岛
// 的 widget、系统翻译的扩展点）都得由这里凭空造进 pbxproj。一个规格描述一个扩展：
//   needle   写在 target 注释里的哨兵 —— 幂等靠它（已经有了就整体跳过），也是 id 前缀的料
//   label    出错与回执里的自称（'widget' / 'translate'），让「跳过了」这件事在输出里说得出口
//   dir      工程里的目录名，同时是 Info.plist 的路径
//   name     target 名 = 产物名 = bundle id 的最后一段
//   deploy   这个扩展自己的部署下限（可以高于 App 本体：App 照常装，只是老系统上没有这个能力）
//   srcDir   源文件在仓库里的目录（`app/native/<srcDir>/`）
//   srcs     要编进去的 Swift 文件（按顺序）
//   plist    这个扩展自己的 Info.plist 正文（<dict> 里那几行）—— 扩展点声明在这里
//   settings 额外的构建设置（键 → 值，原样写进 buildSettings；两档配置共用）
//   resources 要打进扩展 bundle 的资源（`{ name, from }`，from 相对仓库根）
//   productType / productFileType / embed  见下面 EMBED 的注释：**两种扩展不是同一种东西**
//
// **两种扩展点，两种壳**（T1 尖刺 2026-09-19 读出来的，`.local/spike/READINGS.md`）：
// 灵动岛小组件是 `app-extension`，嵌在 `<App>.app/PlugIns/`；系统翻译是 **ExtensionKit**
// （`extensionkit-extension`），嵌在 `<App>.app/Extensions/`，Info.plist 用
// `EXAppExtensionAttributes` 而不是 `NSExtension`。论坛 779334 那个「上传被 ASC 拒」的死结
// （ASC 要 `NSExtensionPrincipalClass`、Xcode 又不许写）正是「拿 app-extension 的壳装这个
// 扩展点」的症状 —— 所以这里不能只换一个字符串，要多一种产品类型和一个独立的嵌入阶段。
const EMBED_PLUGINS = { phase: 'Embed Foundation Extensions' };
const EMBED_EXTENSIONKIT = { phase: 'Embed ExtensionKit Extensions', create: true, dstSubfolderSpec: 16, dstPath: '$(EXTENSIONS_FOLDER_PATH)' };

const WIDGET_SPEC = {
  needle: 'MT_WIDGET_TARGET',
  label: 'widget',
  dir: 'iOS (Widget)',
  name: 'MTPodcastWidget',
  // Live Activity 要 iOS 16.1+，而 App 本体的部署目标更低。
  deploy: '16.1',
  srcDir: 'widget',
  srcs: ['LiveActivity.swift'],
  plist: '\t<key>NSExtension</key>\n\t<dict>\n'
    + '\t\t<key>NSExtensionPointIdentifier</key>\n\t\t<string>com.apple.widgetkit-extension</string>\n'
    + '\t</dict>\n',
  settings: {},
};

// 系统翻译扩展（§9.9 / iOS 线 I-5）。与 widget 的差别全在规格里，代码一行没有分叉。
//   · ExtensionKit：产品类型与嵌入位置都是另一种（见 EMBED_EXTENSIONKIT 上面的注释）
//   · 部署下限 18.4：TranslationUIProvider 从那一版才有。App 本体照常装在更老的系统上，
//     只是那些机器的「设置 › 翻译 › 默认翻译 App」里不会出现我们
//   · ExtEngine.js 打进扩展 bundle：**与 App 同一份字节**的传输栈（domain-design §2.6 规则 2）
//   · 自己的 entitlements：只有 App Group 与共享 Keychain，没有 translation-app、没有
//     applesignin（那两项属于宿主）
const TRANSLATE_EXT_DIR = 'iOS (TranslateExt)';
const TRANSLATE_EXT_SPEC = {
  needle: 'MT_TRANSLATE_EXT_TARGET',
  label: 'translate ext',
  dir: TRANSLATE_EXT_DIR,
  name: 'MTTranslateExt',
  deploy: '18.4',
  srcDir: 'translate-ext',
  // VaultNames 在最前：另外三个都用它。顺序不影响 Swift 编译，但让人一眼看得出依赖。
  srcs: ['VaultNames.swift', 'ExtVault.swift', 'ExtInbox.swift', 'ExtEngineHost.swift', 'ExtCopy.swift', 'TranslateExt.swift'],
  productType: 'com.apple.product-type.extensionkit-extension',
  productFileType: 'wrapper.extensionkit-extension',
  embed: EMBED_EXTENSIONKIT,
  // ExtensionKit 用 EXAppExtensionAttributes，**不是** NSExtension（T1 尖刺）。
  // MTDeepLinkScheme 是我们自己的键：未配置时「打开大肚猴翻译」要用它，而两个 flavor
  // 的 scheme 不同 —— 由 app:sync 按这棵树替换，扩展运行时读 Info.plist。
  plist: '\t<key>EXAppExtensionAttributes</key>\n\t<dict>\n'
    + '\t\t<key>EXExtensionPointIdentifier</key>\n\t\t<string>com.apple.public.translation-ui-provider</string>\n'
    + '\t</dict>\n'
    + '\t<key>MTDeepLinkScheme</key>\n\t<string>__MT_SCHEME__</string>\n',
  settings: {
    CODE_SIGN_ENTITLEMENTS: `"${TRANSLATE_EXT_DIR}/translate-ext.entitlements"`,
    // **系统用扩展的显示名画弹层的标题栏**（T1 真机截图为证）。`$(PRODUCT_NAME)` 会让
    // 那一行写着 `MTTranslateExt` —— 一个只有我们自己认得的内部名字。跟宿主 App 同名。
    INFOPLIST_KEY_CFBundleDisplayName: '"__MT_APP_DISPLAY_NAME__"',
    // iPhone + iPad。系统翻译在两边都有。
    TARGETED_DEVICE_FAMILY: '"1,2"',
  },
  resources: [{ name: 'ExtEngine.js', fromApp: 'ExtEngine.js' }],
  plain: [{ name: 'translate-ext.entitlements', from: 'app/native/entitlements/translate-ext.entitlements' }],
};

// pbxproj 的对象 id 是 24 位十六进制。用固定前缀 + 序号，**不随机** —— 随机 id 会让
// 每次 app:sync 都产生一个不同的 pbxproj，幂等就无从谈起（也没法 diff）。
// 前缀带上 needle 的长度 ⇒ 不同扩展的 id 天然不会撞。
const WID = (spec, n) => 'MT' + spec.needle.length.toString(16).toUpperCase().padStart(2, '0')
  + 'D06CA57E' + String(n).padStart(10, '0');

function patchWidgetTarget(sharedDir) { return patchExtensionTarget(sharedDir, WIDGET_SPEC); }

// 规格里的源文件清单变了怎么办：**拆掉重造**，不缝补。
//
// 对象 id 是按**序号**算出来的（第一个源文件 10/11，其余从 20 起两两排），所以在清单
// 中间插一个文件，后面每一个的 id 都错位一格。第一版是按名字往里补的，于是它以为只缺
// 最后一个，把 TranslateExt.swift 又加了一遍 —— 而工程照样打得开、照样编得过。
//
// 拆掉重造的结果**等于重新生成**：剥掉这个 spec 的全部痕迹（我们自己写的 `MT…` 对象行、
// 带 needle 的那一行、提到产品名的那些行），然后走一遍正常的生成路径。剥的这一段与测试
// 造骨架用的是同一个函数 —— 一份实现两个消费者，所以它被跑得很勤。
function stripExtensionTarget(src, spec) {
  const pfx = 'MT' + spec.needle.length.toString(16).toUpperCase().padStart(2, '0');
  // id 一共 22 位：`MT` + needle 长度的两位十六进制（= pfx，4 位）+ 18 位。
  const id = pfx + '[0-9A-F]{18}';
  // ① 多行对象整块拿掉。只删头一行会留下一段无主的花括号，而那份 pbxproj Xcode 打不开。
  //    负向前瞻把单行对象（`… = {isa = …; };`）排除在外，它们走 ②。
  let out = src.replace(new RegExp('\\n\\t\\t' + id + ' [^\\n]*= \\{(?![^\\n]*\\};)[\\s\\S]*?\\n\\t\\t\\};', 'g'), '');
  // ② 单行对象，以及**任何提到这些 id 的引用行**（targets 列表、某个阶段的 files、
  //    App target 的 buildPhases…）。少删一处引用，重造出来的就是两份。
  out = out.replace(new RegExp('\\n[^\\n]*' + id + '[^\\n]*', 'g'), '');
  // ③ needle 与产品名那几行（产品名还出现在配置里，例如 PRODUCT_BUNDLE_IDENTIFIER）。
  return out.replace(new RegExp('\\n[^\\n]*' + spec.needle + '[^\\n]*', 'g'), '')
    .replace(new RegExp('\\n[^\\n]*' + spec.name + '[^\\n]*', 'g'), '');
}

// 工程里那个 target 还是这份规格描述的那个吗。少一个源文件的症状是「文件在 Xcode 里
// 看得见，却不参与编译」—— 没有一行输出会说，而运行时是一句 `cannot find … in scope`。
function sourcesDrifted(src, spec) {
  return spec.srcs.some((name, i) => !src.includes(WID(spec, i === 0 ? 10 : 20 + (i - 1) * 2)));
}

// 已经造过的 target 里，把显示名那一行升到现在的值。
//
// 「见到 needle 就跳过」是这个补丁的幂等判据，代价是**后来改的设置追不上已有的树**：
// 显示名从 `$(PRODUCT_NAME)` 改成宿主 App 名之后，所有已生成的工程仍然写着
// `MTTranslateExt`，而那一行是系统画在弹层标题栏上的（T1 真机截图）。重新生成整棵树
// 太贵，所以这里原地升级 —— 与 DELEGATE_PATCHES 的 upgrade 同一条思路。
//
// 指纹是**相邻的那一对**：buildSettings 按字母序，`INFOPLIST_FILE` 紧挨着
// `INFOPLIST_KEY_CFBundleDisplayName`，而前者点名了是哪个 target 的哪一档配置。
// 不能按整份 pbxproj 替换 —— 那会把两个 App target 的显示名也改掉。
function upgradeDisplayName(f, src, spec) {
  const want = (spec.settings || {}).INFOPLIST_KEY_CFBundleDisplayName || '';
  if (!want.includes('__MT_APP_DISPLAY_NAME__')) return `${spec.label} target already patched`;
  const appDisplay = ((src.match(/INFOPLIST_KEY_CFBundleDisplayName = "([^"]+)";/g) || [])
    .map((m) => m.match(/"([^"]+)"/)[1])
    .find((v) => !v.startsWith('$(')) || '');
  if (!appDisplay) return `${spec.label} target already patched`;
  const quoted = spec.dir.replace(/[.()]/g, (c) => '\\' + c);
  const re = new RegExp('(INFOPLIST_FILE = "' + quoted + '\\/Info\\.plist";\\n(\\s*)INFOPLIST_KEY_CFBundleDisplayName = )"[^"]*";', 'g');
  let n = 0;
  const out = src.replace(re, (m, head) => {
    if (m.endsWith(`"${appDisplay}";`)) return m;
    n += 1;
    return head + `"${appDisplay}";`;
  });
  if (!n) return `${spec.label} target already patched`;
  fs.writeFileSync(f, out);
  return `${spec.label} target already patched（显示名已升到「${appDisplay}」×${n}）`;
}

// buildSettings 一行。值原样写出（LD_RUNPATH 那种多行的也在内），键按字母序 —— Xcode 自己
// 就是这么排的，而**现有 widget 的那一串正好已经是字母序**，所以 spec.settings 为空时
// 输出逐字节不变（这是 I-1 立下的判据，I-5 不许破）。
const cfgLine = (k, v) => `\t\t\t\t${k} = ${v};\n`;

// 凭空造一个 iOS 扩展 target 并挂进工程：targets 列表、App 的依赖、Embed 阶段。
// 这是整个 sync 里唯一「无中生有」的补丁 —— 别处都是改已有的东西。
function patchExtensionTarget(sharedDir, spec) {
  const appRoot = path.dirname(sharedDir);
  const xcodeproj = fs.readdirSync(appRoot).find((n) => n.endsWith('.xcodeproj'));
  if (!xcodeproj) return `${spec.label}: no xcodeproj`;
  const f = path.join(appRoot, xcodeproj, 'project.pbxproj');
  if (!fs.existsSync(f)) return `${spec.label}: no project.pbxproj`;
  let src = fs.readFileSync(f, 'utf8');
  let rebuilt = false;
  if (src.includes(spec.needle)) {
    if (!sourcesDrifted(src, spec)) return upgradeDisplayName(f, src, spec);
    src = stripExtensionTarget(src, spec);   // 规格变了 ⇒ 拆掉，下面照常重造一遍
    rebuilt = true;
  }

  // 锚点：iOS App target 的 id、它的 Embed 阶段、以及 iOS 扩展的一份 Debug 配置
  // （照抄它的构建设置，只改该改的几项）。任何一个找不到就整体放弃。
  // **不要写死产品名。** 中国版那棵树叫「… CN (iOS)」，写死英文名会让它整体跳过 ——
  // 而「跳过」在这里表现为「中国版没有灵动岛」，没有任何一行输出会说这件事。
  // 按 `productType = application` + SDK 找，才是这个 target 的定义特征。
  const appTarget = src.match(
    /([0-9A-F]{24}) \/\* [^*]*\(iOS\) \*\/ = \{\s*isa = PBXNativeTarget;[\s\S]*?productType = "com\.apple\.product-type\.application";/);
  if (!appTarget) return `✗ ${spec.label}: 找不到 iOS App target —— 转换器布局变了？`;
  const appTargetLabel = (src.match(/([0-9A-F]{24}) \/\* ([^*]*\(iOS\)) \*\/ = \{\s*isa = PBXNativeTarget;[\s\S]*?productType = "com\.apple\.product-type\.application";/) || [])[2];
  // Embed 阶段两个平台各有一个同名的 —— 必须取 **iOS App target 自己列出的那一个**，
  // 否则会把 widget 塞进 macOS App（那儿没有灵动岛，而且 SDK 也对不上）。
  const appTargetId0 = appTarget[1];
  const ids = {
    target: WID(spec, 1), product: WID(spec, 2), group: WID(spec, 3), sources: WID(spec, 4), frameworks: WID(spec, 5),
    resources: WID(spec, 6), cfgList: WID(spec, 7), cfgDebug: WID(spec, 8), cfgRelease: WID(spec, 9),
    dep: WID(spec, 12), proxy: WID(spec, 13), embedFile: WID(spec, 14), embedPhase: WID(spec, 15),
  };
  const em = spec.embed || EMBED_PLUGINS;
  const appPhases = (src.slice(src.indexOf(appTargetId0 + ' /* ')).match(/buildPhases = \(([\s\S]*?)\);/) || [])[1] || '';
  const embedId0 = (appPhases.match(new RegExp('([0-9A-F]{24}) \\/\\* ' + em.phase + ' \\*\\/')) || [])[1];
  // 转换器只生成了 PlugIns 那一个嵌入阶段。ExtensionKit 要的是另一个（`Extensions/`），
  // 工程里根本没有 ⇒ 连阶段本身一起造。**不能塞进 PlugIns 那个**：装错位置的
  // ExtensionKit 扩展不会报错，只是系统永远发现不了它。
  if (!embedId0 && !em.create) return `✗ ${spec.label}: iOS App target 没有 ${em.phase} 阶段`;
  const embedPhaseId = embedId0 || ids.embedPhase;
  const createEmbedPhase = !embedId0;
  if (createEmbedPhase && !src.includes('/* End PBXCopyFilesBuildPhase section */')) {
    return `✗ ${spec.label}: 没有 PBXCopyFilesBuildPhase 段 —— 转换器布局变了？`;
  }
  const deployMatch = src.match(/IPHONEOS_DEPLOYMENT_TARGET = ([0-9.]+);/);
  const marketing = (src.match(/MARKETING_VERSION = ([^;]+);/) || [null, '1.0'])[1];
  const current = (src.match(/CURRENT_PROJECT_VERSION = ([^;]+);/) || [null, '1'])[1];
  const bundlePrefix = (src.match(/PRODUCT_BUNDLE_IDENTIFIER = ([a-zA-Z0-9.]+);/) || [null, 'com.belliedmonkeytranslator'])[1]
    .replace(/\.extension$/, '');

  // 打进扩展 bundle 的资源（ExtEngine.js）。号段 40 起，与源文件（10/11、20…）不重。
  const resIds = (spec.resources || []).map((r, i) => ({
    name: r.name, file: WID(spec, 40 + i * 2), build: WID(spec, 41 + i * 2),
  }));
  // 每个源文件一对 id（引用 + 编译）。第一个沿用 10 / 11（widget 那一版就是这两个号，
  // 保留它才能做到「重构后 widget 的输出逐字节不变」），其余从 20 起两两排。
  const srcIds = spec.srcs.map((name, i) => ({
    name,
    file: WID(spec, i === 0 ? 10 : 20 + (i - 1) * 2),
    build: WID(spec, i === 0 ? 11 : 21 + (i - 1) * 2),
  }));
  const bid = bundlePrefix + '.' + spec.name;

  const baseSettings = {
    ASSETCATALOG_COMPILER_GLOBAL_ACCENT_COLOR_NAME: 'AccentColor',
    CODE_SIGN_STYLE: 'Automatic',
    CURRENT_PROJECT_VERSION: current,
    GENERATE_INFOPLIST_FILE: 'YES',
    INFOPLIST_FILE: `"${spec.dir}/Info.plist"`,
    INFOPLIST_KEY_CFBundleDisplayName: `"${spec.name}"`,
    INFOPLIST_KEY_NSHumanReadableCopyright: '""',
    IPHONEOS_DEPLOYMENT_TARGET: spec.deploy,
    LD_RUNPATH_SEARCH_PATHS: '(\n\t\t\t\t\t"$(inherited)",\n\t\t\t\t\t"@executable_path/Frameworks",\n\t\t\t\t\t"@executable_path/../../Frameworks",\n\t\t\t\t)',
    MARKETING_VERSION: marketing,
    PRODUCT_BUNDLE_IDENTIFIER: bid,
    PRODUCT_NAME: '"$(TARGET_NAME)"',
    SDKROOT: 'iphoneos',
    SKIP_INSTALL: 'YES',
    SWIFT_EMIT_LOC_STRINGS: 'YES',
    SWIFT_VERSION: '5.0',
    TARGETED_DEVICE_FAMILY: '"1,2"',
  };
  // 宿主 App 的显示名。问工程，不写死：它由 build-safari.sh 写进去，而**中文字面量不该
  // 在这份脚本里再抄一份**。认不出来就退回 $(PRODUCT_NAME)（老工程的形状），不阻断。
  const appDisplay = ((src.match(/INFOPLIST_KEY_CFBundleDisplayName = "([^"]+)";/g) || [])
    .map((m) => m.match(/"([^"]+)"/)[1])
    .find((v) => !v.startsWith('$(')) || '$(PRODUCT_NAME)');
  const settings = Object.assign({}, baseSettings, spec.settings || {});
  for (const k of Object.keys(settings)) {
    settings[k] = String(settings[k]).split('__MT_APP_DISPLAY_NAME__').join(appDisplay);
  }
  const settingsText = Object.keys(settings).sort().map((k) => cfgLine(k, settings[k])).join('');
  const cfg = (name) => `\t\t${name === 'Debug' ? ids.cfgDebug : ids.cfgRelease} /* ${name} */ = {\n`
    + '\t\t\tisa = XCBuildConfiguration;\n\t\t\tbuildSettings = {\n'
    + settingsText
    + `\t\t\t};\n\t\t\tname = ${name};\n\t\t};\n`;

  // ① PBXBuildFile：源文件 + 嵌入产物
  src = src.replace('/* End PBXBuildFile section */',
    srcIds.map((x) => `\t\t${x.build} /* ${x.name} in Sources */ = {isa = PBXBuildFile; fileRef = ${x.file} /* ${x.name} */; };\n`).join('')
    + resIds.map((x) => `\t\t${x.build} /* ${x.name} in Resources */ = {isa = PBXBuildFile; fileRef = ${x.file} /* ${x.name} */; };\n`).join('')
    + `\t\t${ids.embedFile} /* ${spec.name}.appex in ${em.phase} */ = {isa = PBXBuildFile; fileRef = ${ids.product} /* ${spec.name}.appex */; settings = {ATTRIBUTES = (RemoveHeadersOnCopy, ); }; };\n`
    + '/* End PBXBuildFile section */');

  // ② PBXFileReference：源文件 + 资源 + 产物
  src = src.replace('/* End PBXFileReference section */',
    srcIds.map((x) => `\t\t${x.file} /* ${x.name} */ = {isa = PBXFileReference; lastKnownFileType = sourcecode.swift; path = ${x.name}; sourceTree = "<group>"; };\n`).join('')
    + resIds.map((x) => `\t\t${x.file} /* ${x.name} */ = {isa = PBXFileReference; lastKnownFileType = sourcecode.javascript; path = ${x.name}; sourceTree = "<group>"; };\n`).join('')
    + `\t\t${ids.product} /* ${spec.name}.appex */ = {isa = PBXFileReference; explicitFileType = "${spec.productFileType || 'wrapper.app-extension'}"; includeInIndex = 0; path = "${spec.name}.appex"; sourceTree = BUILT_PRODUCTS_DIR; };\n`
    + '/* End PBXFileReference section */');

  // ③ PBXGroup：把源文件与资源挂进主 group，产物挂进 Products
  src = src.replace('/* End PBXGroup section */',
    `\t\t${ids.group} /* ${spec.dir} */ = {\n\t\t\tisa = PBXGroup;\n\t\t\tchildren = (\n${srcIds.concat(resIds).map((x) => `\t\t\t\t${x.file} /* ${x.name} */,\n`).join('')}\t\t\t);\n\t\t\tpath = "${spec.dir}";\n\t\t\tsourceTree = SOURCE_ROOT;\n\t\t};\n`
    + '/* End PBXGroup section */');
  const mainGroupId = (src.match(/mainGroup = ([0-9A-F]{24});/) || [])[1];
  if (!mainGroupId) return '✗ widget: 找不到 mainGroup';
  src = src.replace(new RegExp('(' + mainGroupId + ' = \\{\\s*isa = PBXGroup;\\s*children = \\()'),
    `$1\n\t\t\t\t${ids.group} /* ${spec.dir} */,`);
  const productsGroup = src.match(/([0-9A-F]{24}) \/\* Products \*\/ = \{\s*isa = PBXGroup;\s*children = \(/);
  if (!productsGroup) return '✗ widget: 找不到 Products group';
  src = src.replace(productsGroup[0], productsGroup[0] + `\n\t\t\t\t${ids.product} /* ${spec.name}.appex */,`);

  // ④ 三个构建阶段
  src = src.replace('/* End PBXSourcesBuildPhase section */',
    `\t\t${ids.sources} /* Sources */ = {\n\t\t\tisa = PBXSourcesBuildPhase;\n\t\t\tbuildActionMask = 2147483647;\n\t\t\tfiles = (\n${srcIds.map((x) => `\t\t\t\t${x.build} /* ${x.name} in Sources */,\n`).join('')}\t\t\t);\n\t\t\trunOnlyForDeploymentPostprocessing = 0;\n\t\t};\n`
    + '/* End PBXSourcesBuildPhase section */');
  src = src.replace('/* End PBXFrameworksBuildPhase section */',
    `\t\t${ids.frameworks} /* Frameworks */ = {\n\t\t\tisa = PBXFrameworksBuildPhase;\n\t\t\tbuildActionMask = 2147483647;\n\t\t\tfiles = (\n\t\t\t);\n\t\t\trunOnlyForDeploymentPostprocessing = 0;\n\t\t};\n`
    + '/* End PBXFrameworksBuildPhase section */');
  src = src.replace('/* End PBXResourcesBuildPhase section */',
    `\t\t${ids.resources} /* Resources */ = {\n\t\t\tisa = PBXResourcesBuildPhase;\n\t\t\tbuildActionMask = 2147483647;\n\t\t\tfiles = (\n${resIds.map((x) => `\t\t\t\t${x.build} /* ${x.name} in Resources */,\n`).join('')}\t\t\t);\n\t\t\trunOnlyForDeploymentPostprocessing = 0;\n\t\t};\n`
    + '/* End PBXResourcesBuildPhase section */');

  // ⑤ target 本体 —— MT_WIDGET_TARGET 这个 needle 就写在它的注释里
  src = src.replace('/* End PBXNativeTarget section */',
    `\t\t${ids.target} /* ${spec.name} */ = {\n\t\t\tisa = PBXNativeTarget;\n\t\t\t/* ${spec.needle} — patched by scripts/sync-app-assets.js */\n`
    + `\t\t\tbuildConfigurationList = ${ids.cfgList} /* Build configuration list for PBXNativeTarget "${spec.name}" */;\n`
    + `\t\t\tbuildPhases = (\n\t\t\t\t${ids.sources} /* Sources */,\n\t\t\t\t${ids.frameworks} /* Frameworks */,\n\t\t\t\t${ids.resources} /* Resources */,\n\t\t\t);\n`
    + `\t\t\tbuildRules = (\n\t\t\t);\n\t\t\tdependencies = (\n\t\t\t);\n\t\t\tname = ${spec.name};\n\t\t\tproductName = ${spec.name};\n`
    + `\t\t\tproductReference = ${ids.product} /* ${spec.name}.appex */;\n\t\t\tproductType = "${spec.productType || 'com.apple.product-type.app-extension'}";\n\t\t};\n`
    + '/* End PBXNativeTarget section */');

  // ⑥ 配置列表
  src = src.replace('/* End XCConfigurationList section */',
    `\t\t${ids.cfgList} /* Build configuration list for PBXNativeTarget "${spec.name}" */ = {\n\t\t\tisa = XCConfigurationList;\n\t\t\tbuildConfigurations = (\n\t\t\t\t${ids.cfgDebug} /* Debug */,\n\t\t\t\t${ids.cfgRelease} /* Release */,\n\t\t\t);\n\t\t\tdefaultConfigurationIsVisible = 0;\n\t\t\tdefaultConfigurationName = Release;\n\t\t};\n`
    + '/* End XCConfigurationList section */');
  src = src.replace('/* End XCBuildConfiguration section */',
    cfg('Debug') + cfg('Release') + '/* End XCBuildConfiguration section */');

  // ⑦ 挂进工程的 targets 列表
  src = src.replace(/(targets = \(\n)/, `$1\t\t\t\t${ids.target} /* ${spec.name} */,\n`);

  // ⑧ 让 App 依赖它并把 .appex 嵌进去 —— 少了这一步，扩展会编译但装不进 App。
  const appTargetId = appTarget[1];
  src = src.replace('/* End PBXTargetDependency section */',
    `\t\t${ids.dep} /* PBXTargetDependency */ = {\n\t\t\tisa = PBXTargetDependency;\n\t\t\ttarget = ${ids.target} /* ${spec.name} */;\n\t\t\ttargetProxy = ${ids.proxy} /* PBXContainerItemProxy */;\n\t\t};\n`
    + '/* End PBXTargetDependency section */');
  const projectId = (src.match(/([0-9A-F]{24}) \/\* Project object \*\//) || [])[1];
  src = src.replace('/* End PBXContainerItemProxy section */',
    `\t\t${ids.proxy} /* PBXContainerItemProxy */ = {\n\t\t\tisa = PBXContainerItemProxy;\n\t\t\tcontainerPortal = ${projectId} /* Project object */;\n\t\t\tproxyType = 1;\n\t\t\tremoteGlobalIDString = ${ids.target};\n\t\t\tremoteInfo = ${spec.name};\n\t\t};\n`
    + '/* End PBXContainerItemProxy section */');
  // App target：加依赖 + 把 appex 塞进 Embed 阶段
  const appBlock = src.slice(src.indexOf(appTargetId + ' /* ' + appTargetLabel + ' */ = {'));
  const appEnd = appBlock.indexOf('productType = "com.apple.product-type.application";');
  const appSlice = appBlock.slice(0, appEnd);
  let newAppSlice = appSlice.replace(/dependencies = \(\n/, `dependencies = (\n\t\t\t\t${ids.dep} /* PBXTargetDependency */,\n`);
  if (createEmbedPhase) {
    // 新阶段排在 PlugIns 那个之后（顺序不影响正确性，但让两个嵌入阶段挨着，人读得懂）。
    newAppSlice = newAppSlice.replace(
      new RegExp('(\\t+[0-9A-F]{24} \\/\\* ' + EMBED_PLUGINS.phase + ' \\*\\/,\\n)'),
      (m) => m + `\t\t\t\t${embedPhaseId} /* ${em.phase} */,\n`);
    if (!newAppSlice.includes(embedPhaseId)) {
      return `✗ ${spec.label}: iOS App target 的 buildPhases 里挂不上 ${em.phase}`;
    }
  }
  src = src.replace(appSlice, newAppSlice);
  if (createEmbedPhase) {
    src = src.replace('/* End PBXCopyFilesBuildPhase section */',
      `\t\t${embedPhaseId} /* ${em.phase} */ = {\n\t\t\tisa = PBXCopyFilesBuildPhase;\n\t\t\tbuildActionMask = 2147483647;\n`
      + `\t\t\tdstPath = "${em.dstPath}";\n\t\t\tdstSubfolderSpec = ${em.dstSubfolderSpec};\n`
      + `\t\t\tfiles = (\n\t\t\t\t${ids.embedFile} /* ${spec.name}.appex in ${em.phase} */,\n\t\t\t);\n`
      + `\t\t\tname = "${em.phase}";\n\t\t\trunOnlyForDeploymentPostprocessing = 0;\n\t\t};\n`
      + '/* End PBXCopyFilesBuildPhase section */');
  } else {
    src = src.replace(new RegExp('(' + embedPhaseId + ' /\\* ' + em.phase + ' \\*/ = \\{[\\s\\S]*?files = \\(\n)'),
      (m) => m + `\t\t\t\t${ids.embedFile} /* ${spec.name}.appex in ${em.phase} */,\n`);
  }

  fs.writeFileSync(f, src);
  return `${spec.label} target ${rebuilt ? '\u6309\u65b0\u89c4\u683c\u91cd\u9020' : 'patched'} (${spec.name}, iOS ${spec.deploy}+)`;
}

// 扩展的源文件、资源与它自己的 Info.plist。扩展有独立 bundle，所以 plist 也独立。
// 写入是「不一样就覆盖」而不是「不在才写」：这棵工程树是一次性的、随时会被重新生成，
// 手改不该在这里留存；而模板改了却没跟上，表现为「新写的那几行在设备上不存在」，
// 没有任何一行输出会说。
function patchWidgetFiles(sharedDir) { return patchExtensionFiles(sharedDir, WIDGET_SPEC); }

// 模板里的占位符。两个都**必须按这棵树取**，不能写死：两个 flavor 是两个 App ID、
// 两个 scheme，写死会让中国版的扩展去读国际版的 App Group（读不到，且不报错）。
function extSubs(sharedDir) {
  return {
    __MT_APP_BUNDLE_ID__: appBundleId(sharedDir),
    __MT_SCHEME__: schemeFor(sharedDir),
  };
}
function applySubs(text, subs) {
  let out = text;
  for (const k of Object.keys(subs)) out = out.split(k).join(subs[k]);
  return out;
}

function patchExtensionFiles(sharedDir, spec, opts) {
  const appRoot = path.dirname(sharedDir);
  const dir = path.join(appRoot, spec.dir);
  const subs = extSubs(sharedDir);
  const appSrc = (opts && opts.appSrc) || '';
  const put = (dst, text) => {
    if (fs.existsSync(dst) && fs.readFileSync(dst, 'utf8') === text) return;
    fs.writeFileSync(dst, text);
  };
  // 资源来自**这个 flavor 的**宿主 App 包目录（dist-app / dist-app-china）。
  const resFrom = (r) => (r.fromApp ? path.join(appSrc, r.fromApp) : path.join(ROOT, r.from));
  // 先全部检查再写：任何一样缺了就整体放弃 —— 半个扩展比没有扩展更糟，而它编得过。
  for (const name of spec.srcs) {
    if (!fs.existsSync(path.join(ROOT, 'app', 'native', spec.srcDir, name))) {
      return `✗ ${spec.label}: app/native/${spec.srcDir}/${name} 不存在`;
    }
  }
  for (const r of spec.resources || []) {
    if (r.fromApp && !appSrc) return `✗ ${spec.label}: 没告诉我这棵树的宿主 App 包目录`;
    if (!fs.existsSync(resFrom(r))) {
      return `✗ ${spec.label}: ${r.fromApp || r.from} 不存在 —— 先跑 node build.js`;
    }
  }
  for (const p of spec.plain || []) {
    if (!fs.existsSync(path.join(ROOT, p.from))) return `✗ ${spec.label}: ${p.from} 不存在`;
  }
  if ((spec.plain || []).length && !subs.__MT_APP_BUNDLE_ID__) {
    return `✗ ${spec.label}: 工程里读不到 App 的 bundle id —— entitlements 会指向一个不存在的组`;
  }
  fs.mkdirSync(dir, { recursive: true });
  for (const name of spec.srcs) {
    put(path.join(dir, name), fs.readFileSync(path.join(ROOT, 'app', 'native', spec.srcDir, name), 'utf8'));
  }
  for (const r of spec.resources || []) put(path.join(dir, r.name), fs.readFileSync(resFrom(r), 'utf8'));
  for (const p of spec.plain || []) {
    put(path.join(dir, p.name), applySubs(fs.readFileSync(path.join(ROOT, p.from), 'utf8'), subs));
  }
  put(path.join(dir, 'Info.plist'), '<?xml version="1.0" encoding="UTF-8"?>\n'
    + '<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">\n'
    + '<plist version="1.0">\n<dict>\n' + applySubs(spec.plist, subs) + '</dict>\n</plist>\n');
  return `${spec.label} files synced`;
}

function main() {
  let touched = 0;
  // Notes that start with ✗ are failures, and they used to disappear into the middle
  // of a ✓ line. For the §9.5 patches that is not survivable: a missing background
  // patch produces an app that installs fine and goes silent the moment the screen
  // locks — indistinguishable from the feature not being built. Collect and exit 1.
  // Only the new patches emit ✗; the older ones keep their soft wording so a
  // half-generated tree does not start failing for unrelated reasons.
  const problems = [];
  const loud = (proj, label, note) => {
    if (/^✗/.test(note)) problems.push(`${proj} · ${label}: ${note.replace(/^✗\s*/, '')}`);
    return note;
  };
  for (const proj of PROJECTS) {
    const { state, dirs } = classifyProject(path.join(ROOT, proj));
    if (state === 'absent') { console.log(`  – ${proj}: 未生成，跳过`); continue; }
    // 源目录按工程决定，且**缺了就停**，不回落到另一个 flavor 的包 —— 回落正是上一版
    // 出问题的形状：中国版工程拿到了国际版资源，而全程没有一行警告。
    const SRC = path.join(ROOT, APP_SRC[proj]);
    if (!fs.existsSync(SRC)) {
      console.error(`✗ ${proj} 需要 ${APP_SRC[proj]}/，但它不存在`);
      console.error(`  跑 node build.js${APP_SRC[proj].endsWith('-china') ? ' --flavor china' : ''} 先出这个 flavor 的宿主 App 包`);
      process.exit(1);
    }
    for (const f of FILES) {
      if (!fs.existsSync(path.join(SRC, f))) {
        console.error(`✗ ${APP_SRC[proj]}/${f} 缺失 —— 宿主 App 包没构建完整`);
        process.exit(1);
      }
    }
    // 过期比缺失更坏，因为它一声不吭。上面那条只拦「没有」，拦不住「有，但是旧的」：
    // 2026-08-28 只跑了 `node build.js`（global），dist-app-china/ 还停在两天前，
    // app:sync 就把旧资源忠实地灌进了中国版工程，并打印「✓ 资源已灌入」。
    // 装出来的中国版 App 少了整套引导，而没有任何一行说过。
    const newestSrc = newestMtime([
      path.join(ROOT, 'app'),
      path.join(ROOT, 'extension', '_locales'),   // i18n 也编进 Script.js
    ]);
    const oldestBuilt = Math.min(...FILES.map((f) => fs.statSync(path.join(SRC, f)).mtimeMs));
    if (newestSrc > oldestBuilt) {
      const flag = APP_SRC[proj].endsWith('-china') ? ' --flavor china' : '';
      console.error(`✗ ${APP_SRC[proj]}/ 比源码旧 —— 灌进去的会是过期资源`);
      console.error(`  源码最新改动：${new Date(newestSrc).toLocaleString()}`);
      console.error(`  包体构建时间：${new Date(oldestBuilt).toLocaleString()}`);
      console.error(`  修法：node build.js${flag}   然后再跑 app:sync`);
      process.exit(1);
    }
    if (state === 'unrecognized') {
      console.error(`✗ ${proj}/ 存在，但里面找不到 "Shared (App)" —— 这个工程无法打补丁。`);
      console.error('  这是单平台的扁平布局（--ios-only / --macos-only，或旧版转换器生成的树）。');
      console.error('  它拿不到宿主 App 的资源，也拿不到滚动 / 媒体门 / 麦克风声明 /');
      console.error('  audio-input 四个补丁 —— 装出来的 App 是转换器的模板页，不是我们的 App。');
      console.error(`  修法：删掉重生成 —— rm -rf ${proj} && bash build-safari.sh <flavor> <platform>`);
      console.error('  （现在的脚本一个 flavor 只出一棵双平台树，iOS 与 macOS 共用。）');
      process.exit(1);
    }
    for (const shared of dirs) {
      const res = path.join(shared, 'Resources');
      const lproj = path.join(res, 'Base.lproj');
      if (!fs.existsSync(res)) { console.error(`✗ ${proj}: 没有 Resources/`); process.exit(1); }
      fs.mkdirSync(lproj, { recursive: true });
      // Main.html lives in Base.lproj (localizable); the other two sit beside it in
      // Resources/. That split is the converter's, not ours — matching it is what
      // keeps the pbxproj untouched.
      fs.copyFileSync(path.join(SRC, 'Main.html'), path.join(lproj, 'Main.html'));
      fs.copyFileSync(path.join(SRC, 'Script.js'), path.join(res, 'Script.js'));
      fs.copyFileSync(path.join(SRC, 'Style.css'), path.join(res, 'Style.css'));
      const vc = loud(proj, 'ViewController', patchViewController(shared));
      const bridge = loud(proj, 'audio bridge', patchAudioBridge(shared));
      const plists = loud(proj, 'Info.plist', patchInfoPlists(shared)) + ' · ' + loud(proj, 'InfoPlist.strings', patchInfoPlistStrings(shared))
        + ' · ' + loud(proj, 'ServicesMenu.strings', patchServicesMenuStrings(shared));
      const dlg = loud(proj, 'delegates', patchDelegates(shared));
      // 灵动岛（§9.5）：只做 iOS，且只对已经带 iOS App target 的工程。macOS 没有灵动岛。
      const hasIOS = fs.existsSync(path.join(path.dirname(shared), 'iOS (App)'));
      const widget = hasIOS
        ? loud(proj, 'widget', patchWidgetFiles(shared)) + ' · '
          + loud(proj, 'widget', patchWidgetTarget(shared))
        : 'widget: 无 iOS App target，跳过';
      // 系统翻译（§9.9 / I-5）：同样只做 iOS。macOS 没有 TranslationUIProvider ——
      // Apple 至今没有对应物，所以那边不是「以后再说」，是根本没有这个扩展点。
      const transExt = hasIOS
        ? loud(proj, 'translate ext', patchExtensionFiles(shared, TRANSLATE_EXT_SPEC, { appSrc: SRC })) + ' · '
          + loud(proj, 'translate ext', patchExtensionTarget(shared, TRANSLATE_EXT_SPEC))
        : 'translate ext: 无 iOS App target，跳过';
      console.log(`  ✓ ${proj}: 资源已灌入 · ViewController ${vc} · ${bridge} · ${widget} · ${transExt} · Info.plist ${plists} · ${dlg} · pbxproj ${patchPbxproj(shared)} · ${loud(proj, 'sherpa package', patchSwiftPackage(shared))} · ${patchEntitlements(shared)} · storyboard ${patchMacWindow(shared)} · ${patchMacMenu(shared)} · ${patchAppIcon(shared)}`);
      touched++;
    }
  }

  if (!touched) {
    console.error('✗ 没有找到任何已生成的 Safari 工程 —— 先跑 safari-web-extension-converter');
    process.exit(1);
  }
  if (problems.length) {
    console.error('\n✗ 有补丁没打上 —— 装出来的 App 会缺功能，而 Xcode 不会说任何话：');
    for (const x of problems) console.error('  ' + x);
    process.exit(1);
  }

  console.log('\n注意：Xcode 增量构建不一定会重拷改动过的资源。测 App 资源前先 rm -rf derivedData。');
}

if (require.main === module) main();

module.exports = {
  classifyProject, patchViewController, patchMacWindowXml, patchMacMenuXml,
  patchAudioBridgeSwift, patchMarkerBlockSwift, BLOCKS, patchSwiftPackageText, patchMacDeploymentTarget, patchDeploymentTargets,
  patchPlistXml, patchInfoPlists, PLIST_KEYS,
  PLIST_L10N, PLIST_L10N_KEYS, infoPlistStringsText, patchPbxprojInfoPlistStrings, patchInfoPlistStrings,
  SERVICES_L10N, SERVICE_MESSAGE, SERVICE_TITLE_EN, servicesXml, servicesMenuStringsText, patchPbxprojStringsGroup, patchServicesMenuStrings,
  patchEntitlements, ENTITLEMENTS,
  patchWidgetTarget, patchExtensionTarget, WIDGET_SPEC, patchWidgetFiles, patchExtensionFiles,
  EMBED_PLUGINS, EMBED_EXTENSIONKIT, TRANSLATE_EXT_SPEC, appBundleId, stripExtensionTarget, openUrlHosts, patchDelegates, DELEGATE_PATCHES,
};
